"use client";

import React from 'react';
import { Lightbulb, AlertTriangle, CheckCircle, Info, TrendingUp } from 'lucide-react';

interface BudgetData {
    budgetName: string;
    totalBudgetAmount: number;
    totalTransactionsAmount: number;
}

interface BudgetAdvisorProps {
    budgetData: BudgetData[];
    savingsGoals: any[]; // Using any for now to avoid complexity, will cast inside
}

const BudgetAdvisor: React.FC<BudgetAdvisorProps> = ({ budgetData, savingsGoals }) => {
    const getAdvice = () => {
        const adviceList: { icon: React.ReactNode; title: string; text: string; type: 'success' | 'warning' | 'error' | 'info' }[] = [];

        // Analysis of savings goals
        savingsGoals.forEach(goal => {
            const percentage = (goal.currentAmount / goal.targetAmount) * 100;
            if (percentage >= 100) {
                adviceList.push({
                    icon: <CheckCircle className="text-green-500" />,
                    title: `Objectif atteint ! 🎉`,
                    text: `Félicitations ! Vous avez atteint votre objectif "${goal.name}". C'est le moment de célébrer !`,
                    type: 'success'
                });
            } else if (percentage >= 75) {
                adviceList.push({
                    icon: <TrendingUp className="text-accent" />,
                    title: `Presque là : ${goal.name}`,
                    text: `Vous avez atteint ${Math.round(percentage)}% de votre objectif. Encore un petit effort !`,
                    type: 'info'
                });
            }
        });

        if (budgetData.length === 0 && savingsGoals.length === 0) {
            adviceList.push({
                icon: <Info className="text-blue-500" />,
                title: "Commencez votre voyage",
                text: "Créez votre premier budget pour commencer à recevoir des conseils personnalisés.",
                type: 'info'
            });
            return adviceList;
        }

        budgetData.forEach(budget => {
            const percentage = (budget.totalTransactionsAmount / budget.totalBudgetAmount) * 100;

            if (percentage >= 100) {
                adviceList.push({
                    icon: <AlertTriangle className="text-red-500" />,
                    title: `Budget dépassé : ${budget.budgetName}`,
                    text: `Vous avez dépassé votre budget de ${Math.round(percentage - 100)}%. Envisagez de réduire vos dépenses dans cette catégorie le mois prochain.`,
                    type: 'error'
                });
            } else if (percentage >= 80) {
                adviceList.push({
                    icon: <AlertTriangle className="text-yellow-500" />,
                    title: `Attention : ${budget.budgetName}`,
                    text: `Vous avez utilisé ${Math.round(percentage)}% de votre budget. Il reste peu de marge, soyez vigilant !`,
                    type: 'warning'
                });
            } else if (percentage < 30 && budget.totalTransactionsAmount > 0) {
                adviceList.push({
                    icon: <CheckCircle className="text-green-500" />,
                    title: `Excellent travail : ${budget.budgetName}`,
                    text: `Vous gérez très bien ce budget (seulement ${Math.round(percentage)}% utilisé). Continuez comme ça !`,
                    type: 'success'
                });
            }
        });

        // General financial tips if not many alerts
        if (adviceList.length < 3) {
            adviceList.push({
                icon: <Lightbulb className="text-amber-500" />,
                title: "Conseil Épargne",
                text: "Essayez d'épargner au moins 20% de vos revenus chaque mois pour construire un fonds d'urgence.",
                type: 'info'
            });
            adviceList.push({
                icon: <Lightbulb className="text-amber-500" />,
                title: "Règle 50/30/20",
                text: "Considérez la règle 50% pour les besoins, 30% pour les envies et 20% pour l'épargne.",
                type: 'info'
            });
        }

        return adviceList.slice(0, 4); // Show top 4 advices
    };

    const advices = getAdvice();

    return (
        <div className="mt-6 border-2 border-base-300 p-5 rounded-xl bg-base-100 shadow-sm">
            <div className="flex items-center gap-2 mb-4">
                <Lightbulb className="text-accent w-6 h-6" />
                <h3 className="text-xl font-bold italic text-accent">Conseiller Intelligent</h3>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
                {advices.map((advice, index) => (
                    <div key={index} className="flex gap-4 p-4 rounded-lg bg-base-200/50 border border-base-300">
                        <div className="mt-1 flex-shrink-0">
                            {advice.icon}
                        </div>
                        <div>
                            <h4 className="font-bold text-md mb-1">{advice.title}</h4>
                            <p className="text-sm opacity-70 leading-relaxed font-medium italic">
                                "{advice.text}"
                            </p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default BudgetAdvisor;

"use client";

import React, { useState } from 'react';
import { Target, Plus, Trash2, TrendingUp } from 'lucide-react';
import { SavingsGoal } from '@/type';
import { addSavingsGoal, deleteSavingsGoal, updateSavingsGoalAmount } from '../actions';

interface SavingsGoalItemProps {
    goal: SavingsGoal;
    onUpdate: () => void;
}

const SavingsGoalItem: React.FC<SavingsGoalItemProps> = ({ goal, onUpdate }) => {
    const [amountToAdd, setAmountToAdd] = useState<string>("");
    const percentage = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);

    const handleAddFunds = async () => {
        const amount = parseFloat(amountToAdd);
        if (isNaN(amount) || amount <= 0) return;

        try {
            await updateSavingsGoalAmount(goal.id, amount);
            setAmountToAdd("");
            onUpdate();
        } catch (error) {
            console.error("Erreur lors de l'ajout de fonds:", error);
        }
    };

    const handleDelete = async () => {
        if (confirm("Voulez-vous vraiment supprimer cet objectif ?")) {
            try {
                await deleteSavingsGoal(goal.id);
                onUpdate();
            } catch (error) {
                console.error("Erreur lors de la suppression de l'objectif:", error);
            }
        }
    };

    return (
        <div className="border-2 border-base-300 p-5 rounded-xl bg-base-100 shadow-sm">
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <div className="bg-accent/10 p-2 rounded-lg">
                        <Target className="text-accent w-6 h-6" />
                    </div>
                    <div>
                        <h3 className="text-lg font-bold">{goal.name}</h3>
                        <p className="text-sm text-gray-500">
                            Cible : {goal.targetAmount} FCFA
                        </p>
                    </div>
                </div>
                <button onClick={handleDelete} className="btn btn-ghost btn-sm text-error">
                    <Trash2 size={18} />
                </button>
            </div>

            <div className="mb-4">
                <div className="flex justify-between text-sm mb-1">
                    <span>Progression</span>
                    <span className="font-bold">{Math.round(percentage)}%</span>
                </div>
                <progress className="progress progress-accent w-full h-3" value={percentage} max="100"></progress>
                <div className="flex justify-between text-xs mt-1 text-gray-500">
                    <span>{goal.currentAmount} FCFA épargnés</span>
                    <span>Reste : {Math.max(goal.targetAmount - goal.currentAmount, 0)} FCFA</span>
                </div>
            </div>

            <div className="flex gap-2">
                <input
                    type="number"
                    placeholder="Montant à ajouter"
                    className="input input-bordered input-sm flex-1"
                    value={amountToAdd}
                    onChange={(e) => setAmountToAdd(e.target.value)}
                />
                <button onClick={handleAddFunds} className="btn btn-accent btn-sm">
                    Épargner
                </button>
            </div>
        </div>
    );
};

export default SavingsGoalItem;

"use client"

import { useUser } from '@clerk/nextjs';
import { useCallback, useEffect, useState } from 'react'
import { getLastBudgets, getLastTransactions, getReachedBudgets, getSavingsGoals, getTotalTransactionAmount, getTotalTransactionCount, getUserBudgetData, syncRecurringTransactions, getBudgetInsights, getSmartCategorization, addTransactionToBudget } from '../actions';
import Wrapper from '../components/Wrapper';
import { CircleDollarSign, Landmark, PiggyBank, FileDown, Zap, CalendarDays } from 'lucide-react';
import Notification from '../components/Notification';
import { generatePDF } from '@/lib/pdfGenerator';
import { Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis } from 'recharts';
import { Budget, Transaction } from '@/type';
import BudgetItem from '../components/BudgetItem';
import Link from 'next/link';
import TransactionItem from '../components/TransactionItem';
import BudgetAdvisor from '../components/BudgetAdvisor';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#AF19FF', '#FF1943'];

const Page = () => {
    const { user } = useUser();
    const [totalAmount, setTotalAmount] = useState<number | null>(null)
    const [isLoading, setIsLoading] = useState(true);
    const [totalCount, setTotalCount] = useState<number | null>(null)
    const [reachedBudgetsRatio, setReachedBudgetsRatio] = useState<string | null>(null);
    interface BudgetData {
        budgetName: string;
        totalBudgetAmount: number;
        totalTransactionsAmount: number;
    }
    const [budgetData, setBudgetData] = useState<BudgetData[]>([]);
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [budgets, setBudgets] = useState<Budget[]>([]);
    const [savingsGoals, setSavingsGoals] = useState<any[]>([]);

    // Insights & Quick Add state
    const [insights, setInsights] = useState<{ dailyAllowance: number; warnings: string[] } | null>(null);
    const [quickAddDesc, setQuickAddDesc] = useState('');
    const [quickAddAmount, setQuickAddAmount] = useState('');
    const [isQuickAdding, setIsQuickAdding] = useState(false);
    const [notification, setNotification] = useState<string>("");


    const fetchData = useCallback(async () => {
        setIsLoading(true)
        try {
            const email = user?.primaryEmailAddress?.emailAddress as string
            if (email) {
                // Execute all promises in parallel for better performance
                const [
                    _syncResult,
                    amount,
                    count,
                    reachedBudgets,
                    budgetsData,
                    lastTransactions,
                    lastBudgets,
                    goalsData,
                    insightsData
                ] = await Promise.all([
                    syncRecurringTransactions(email), // Runs in parallel
                    getTotalTransactionAmount(email),
                    getTotalTransactionCount(email),
                    getReachedBudgets(email),
                    getUserBudgetData(email),
                    getLastTransactions(email),
                    getLastBudgets(email),
                    getSavingsGoals(email),
                    getBudgetInsights(email)
                ]);

                setTotalAmount(amount)
                setTotalCount(count)
                setReachedBudgetsRatio(reachedBudgets)
                setBudgetData(budgetsData)
                setTransactions(lastTransactions)
                setBudgets(lastBudgets)
                setSavingsGoals(goalsData)
                setInsights(insightsData)
                setIsLoading(false)

            }
        } catch (error) {
            console.error("Erreur lors de la récupération des données:", error);
            setIsLoading(false)
        }
    }, [user?.primaryEmailAddress?.emailAddress]);

    useEffect(() => {
        fetchData()
    }, [fetchData])

    const handleQuickAdd = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!quickAddDesc || !quickAddAmount) return;

        setIsQuickAdding(true);
        try {
            const email = user?.primaryEmailAddress?.emailAddress as string;
            const amountNum = parseFloat(quickAddAmount);

            // 1. Smart categorize
            const suggestedBudget = await getSmartCategorization(email, quickAddDesc);

            if (!suggestedBudget) {
                setNotification("Erreur: Vous n'avez pas de budget existant pour classer cette dépense.");
                setIsQuickAdding(false);
                return;
            }

            // 2. Add transaction
            await addTransactionToBudget(suggestedBudget.id, amountNum, quickAddDesc);

            setNotification(`Transaction ajoutée au budget "${suggestedBudget.name}" (${suggestedBudget.emoji})`);
            setQuickAddDesc('');
            setQuickAddAmount('');
            fetchData(); // Refresh dashboard
        } catch (error) {
            console.error("Erreur Ajout Rapide", error);
            setNotification("Impossible d'ajouter la transaction pour le moment. Vérifiez si vous dépassez le montant.");
        } finally {
            setIsQuickAdding(false);
        }
    }

    return (
        <Wrapper>
            {notification && <Notification message={notification} onclose={() => setNotification("")} />}
            {isLoading ? (
                <div className='flex justify-center items-center'>
                    <span className="loading loading-spinner loading-md"></span>
                </div>
            ) : (
                <div>
                    <div className="flex justify-between items-center mb-6">
                        <h1 className="text-3xl font-bold">Tableau de Bord</h1>
                        <button onClick={() => generatePDF(transactions, totalAmount || 0, totalCount || 0)} className="btn btn-accent btn-sm md:btn-md text-white">
                            <FileDown className="w-4 h-4 mr-2" /> Télécharger le rapport
                        </button>
                    </div>

                    {insights?.warnings && insights.warnings.length > 0 && (
                        <div className="alert alert-warning shadow-sm mb-6">
                            <svg xmlns="http://www.w3.org/2000/svg" className="stroke-current shrink-0 h-6 w-6" fill="none" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                            <span>Attention: Vos budgets <b>{insights.warnings.join(', ')}</b> ont dépassé 90% de leur limite !</span>
                        </div>
                    )}

                    <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4'>
                        <div className='border-2 border-base-300 p-5 flex justify-between items-center rounded-xl '>
                            <div className='flex flex-col'>
                                <span className='text-gray-500 text-sm'>
                                    Total des transactions
                                </span>
                                <span className='text-2xl font-bold text-accent'>
                                    {totalAmount !== null ? `${totalAmount} FCFA` : 'N/A'}
                                </span>
                            </div>
                            <CircleDollarSign className='bg-accent w-9 h-9 rounded-full p-1 text-white' />
                        </div>

                        <div className='border-2 border-base-300 p-5 flex justify-between items-center rounded-xl '>
                            <div className='flex flex-col'>
                                <span className='text-gray-500 text-sm'>
                                    Nombre de transactions
                                </span>
                                <span className='text-2xl font-bold text-accent'>
                                    {totalCount !== null ? `${totalCount}` : 'N/A'}
                                </span>
                            </div>
                            <PiggyBank className='bg-accent w-9 h-9 rounded-full p-1 text-white' />
                        </div>

                        <div className='border-2 border-base-300 p-5 flex justify-between items-center rounded-xl '>
                            <div className='flex flex-col'>
                                <span className='text-gray-500 text-sm'>
                                    Budgets atteints
                                </span>
                                <span className='text-2xl font-bold text-accent'>
                                    {reachedBudgetsRatio || 'N/A'}
                                </span>
                            </div>
                            <Landmark className='bg-accent w-9 h-9 rounded-full p-1 text-white' />
                        </div>

                        <div className='border-2 border-base-300 p-5 flex justify-between items-center rounded-xl bg-accent/10'>
                            <div className='flex flex-col'>
                                <span className='text-gray-500 text-sm font-medium'>
                                    Allocation Journalière
                                </span>
                                <span className='text-2xl font-bold text-accent'>
                                    {insights !== null ? `${insights.dailyAllowance} FCFA` : 'N/A'}
                                </span>
                            </div>
                            <CalendarDays className='text-accent w-9 h-9 p-1' />
                        </div>
                    </div>

                    <div className='w-full md:flex mt-4'>
                        <div className='md:w-2/3'>
                            <div className='border-2 border-base-300 p-5 rounded-xl'>
                                <div className='grid md:grid-cols-2 gap-4'>
                                    <div>
                                        <h3 className='text-lg font-semibold mb-3'>
                                            Statistiques ( en FCFA )
                                        </h3>
                                        <ResponsiveContainer height={250} width="100%">
                                            <BarChart width={730} height={250} data={budgetData}>
                                                <CartesianGrid vertical={false} strokeDasharray="3 3" />
                                                <XAxis dataKey="budgetName" />
                                                <Tooltip />
                                                <Bar
                                                    name="Budget"
                                                    dataKey="totalBudgetAmount"
                                                    fill="#EF9FBC"
                                                    radius={[10, 10, 0, 0]}
                                                />
                                                <Bar
                                                    name="Dépensé"
                                                    dataKey="totalTransactionsAmount" fill="#EEAF3A"
                                                    radius={[10, 10, 0, 0]}
                                                />
                                            </BarChart>
                                        </ResponsiveContainer>
                                    </div>
                                    <div>
                                        <h3 className='text-lg font-semibold mb-3'>
                                            Répartition des dépenses
                                        </h3>
                                        <ResponsiveContainer height={250} width="100%">
                                            <PieChart>
                                                <Pie
                                                    data={budgetData}
                                                    dataKey="totalTransactionsAmount"
                                                    nameKey="budgetName"
                                                    cx="50%"
                                                    cy="50%"
                                                    outerRadius={80}
                                                    fill="#8884d8"
                                                    label
                                                >
                                                    {budgetData.map((entry, index) => (
                                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                                    ))}
                                                </Pie>
                                                <Tooltip />
                                            </PieChart>
                                        </ResponsiveContainer>
                                    </div>
                                </div>
                            </div>

                            <BudgetAdvisor budgetData={budgetData} savingsGoals={savingsGoals} />

                            <div className='mt-4 border-2 border-base-300 p-5 rounded-xl'>
                                <h3 className='text-lg font-semibold  mb-3'>
                                    Dernières Transactions
                                </h3>
                                <ul className='divide-y divide-base-300'>
                                    {transactions.map((transaction) => (
                                        <TransactionItem
                                            key={transaction.id}
                                            transaction={transaction}>
                                        </TransactionItem>
                                    ))}
                                </ul>
                            </div>
                        </div>

                        <div className='md:w-1/3 md:ml-4 flex flex-col'>
                            {/* Widget d'ajout rapide */}
                            <div className='bg-base-200/50 border-2 border-base-300 p-5 rounded-xl mb-6'>
                                <div className='flex items-center gap-2 mb-3'>
                                    <Zap className="text-accent w-5 h-5" fill="currentColor" />
                                    <h3 className='text-lg font-bold'>Ajout Rapide Intelligent</h3>
                                </div>
                                <p className='text-sm text-gray-500 mb-4'>Saisissez une dépense, l&apos;IA la classe automatiquement !</p>
                                <form onSubmit={handleQuickAdd} className='flex flex-col gap-3'>
                                    <input
                                        type="text"
                                        placeholder="Ex: Supermarché, Cinéma..."
                                        className='input input-bordered w-full input-sm'
                                        value={quickAddDesc}
                                        onChange={e => setQuickAddDesc(e.target.value)}
                                        required
                                    />
                                    <div className='flex gap-2'>
                                        <input
                                            type="number"
                                            placeholder="Montant"
                                            className='input input-bordered w-full input-sm'
                                            value={quickAddAmount}
                                            onChange={e => setQuickAddAmount(e.target.value)}
                                            required
                                        />
                                        <button
                                            type="submit"
                                            className='btn btn-accent btn-sm text-white'
                                            disabled={isQuickAdding}
                                        >
                                            {isQuickAdding ? <span className="loading loading-spinner loading-xs"></span> : "Ajouter"}
                                        </button>
                                    </div>
                                </form>
                            </div>

                            <h3 className='text-lg font-semibold mb-4'>
                                Derniers Budgets
                            </h3>
                            <ul className="grid grid-cols-1 gap-4">
                                {budgets.map((budget) => (
                                    <Link href={`/manage/${budget.id}`} key={budget.id}>
                                        <BudgetItem budget={budget} enableHover={1}></BudgetItem>
                                    </Link>
                                ))}
                            </ul>
                        </div>
                    </div>
                </div>
            )}
        </Wrapper>
    )
}

export default Page;

"use client"
import { addRecurringTransaction, addTransactionToBudget, deleteBudget, deleteTransaction, getRecurringTransactionsByBudget, getTrasactionsByBudgetId, updateBudget, updateTransaction } from '@/app/actions'
import BudgetItem from '@/app/components/BudgetItem'
import Wrapper from '@/app/components/Wrapper'
import { Budget, RecurringTransaction } from '@/type'
import React, { useCallback, useEffect, useState } from 'react'
import Notification from '@/app/components/Notification'
import { Send, Trash, Pencil } from 'lucide-react'
import { redirect } from 'next/navigation'
import EmojiPicker from 'emoji-picker-react'
import RecurringTransactionList from '@/app/components/RecurringTransactionList'

const Page = ({ params }: { params: Promise<{ budgetId: string }> }) => {
  const [budgetId, setBudgetId] = useState<string>('')
  const [budget, setBudget] = useState<Budget>()
  const [description, setDescription] = useState<string>('')
  const [amount, setAmount] = useState<string>('')
  const [isRecurring, setIsRecurring] = useState<boolean>(false)
  const [frequency, setFrequency] = useState<string>('MONTHLY')
  const [recurringTransactions, setRecurringTransactions] = useState<RecurringTransaction[]>([])

  const [notification, setNotification] = useState<string>("");
  const closeNotification = () => {
    setNotification("")
  }

  // Edit Budget State
  const [isEditBudgetModalOpen, setIsEditBudgetModalOpen] = useState(false)
  const [editBudgetName, setEditBudgetName] = useState('')
  const [editBudgetAmount, setEditBudgetAmount] = useState('')
  const [editBudgetEmoji, setEditBudgetEmoji] = useState('')
  const [showEmojiPicker, setShowEmojiPicker] = useState(false)

  // Edit Transaction State
  const [editingTransactionId, setEditingTransactionId] = useState<string | null>(null)
  const [editTransactionDescription, setEditTransactionDescription] = useState('')
  const [editTransactionAmount, setEditTransactionAmount] = useState('')
  const [editTransactionAmountString, setEditTransactionAmountString] = useState('')

  const fetchBudgetData = useCallback(async (budgetId: string) => {
    try {
      if (budgetId) {
        const budgetData = await getTrasactionsByBudgetId(budgetId)
        const recurringData = await getRecurringTransactionsByBudget(budgetId)
        setBudget(budgetData)
        setRecurringTransactions(recurringData)
        setEditBudgetName(budgetData?.name || '')
        setEditBudgetAmount(budgetData?.amount.toString() || '')
        setEditBudgetEmoji(budgetData?.emoji || '')
      }

    } catch (error) {
      console.error(
        "Erreur lors de la récupération du budget et des transactions:",
        error)
    }
  }, []);

  useEffect(() => {
    const getId = async () => {
      const resolvedParams = await params;
      setBudgetId(resolvedParams.budgetId)
      fetchBudgetData(resolvedParams.budgetId)
    }
    getId()
  }, [params, fetchBudgetData])

  const handleAddTransaction = async () => {
    if (!amount || !description) {
      setNotification("Veuillez remplir tous les champs.")
      return;
    }

    try {
      const amountNumber = parseFloat(amount);
      if (isNaN(amountNumber) || amountNumber <= 0) {
        throw new Error("Le montant doit être un nombre positif.");
      }
      if (isRecurring) {
        await addRecurringTransaction(budgetId, amountNumber, description, frequency)
        setNotification(`Transaction récurrente ajoutée avec succès`)
      } else {
        await addTransactionToBudget(budgetId, amountNumber, description)
        setNotification(`Transaction ajoutée avec succès`)
      }

      fetchBudgetData(budgetId)
      setAmount('')
      setDescription('')
      setIsRecurring(false)
    } catch {
      setNotification(`Vous avez dépassé votre budget ou une erreur est survenue`)
    }
  }

  const handleDeleteBudget = async () => {
    const comfirmed = window.confirm(
      "Êtes-vous sûr de vouloir supprimer ce budget et toutes ses transactions associées ?"
    )
    if (comfirmed) {
      try {
        await deleteBudget(budgetId)
      } catch (error) {
        console.error("Erreur lors de la suppression du budget:", error);
      }
      redirect("/budgets")
    }
  }

  const handleDeleteTransaction = async (transactionId: string) => {
    const comfirmed = window.confirm(
      "Êtes-vous sûr de vouloir supprimer cette transaction ?"
    )
    if (comfirmed) {
      try {
        await deleteTransaction(transactionId)
        fetchBudgetData(budgetId)
        setNotification("Dépense supprimée")
      } catch (error) {
        console.error("Erreur lors de la suppression du budget:", error);
      }
    }
  }

  // Update Budget Logic
  const handleUpdateBudget = async () => {
    try {
      const amountNum = parseFloat(editBudgetAmount);
      if (isNaN(amountNum) || amountNum <= 0) throw new Error("Montant invalide");

      await updateBudget(budgetId, editBudgetName, amountNum, editBudgetEmoji);
      setNotification("Budget mis à jour avec succès");
      setIsEditBudgetModalOpen(false);
      fetchBudgetData(budgetId);
    } catch (error) {
      setNotification("Erreur lors de la mise à jour du budget");
      console.error(error);
    }
  }

  // Update Transaction Logic
  const openEditTransactionModal = (transaction: any) => {
    setEditingTransactionId(transaction.id);
    setEditTransactionDescription(transaction.description);
    setEditTransactionAmount(transaction.amount.toString());
    (document.getElementById('edit_transaction_modal') as HTMLDialogElement)?.showModal();
  }

  const handleUpdateTransaction = async () => {
    if (!editingTransactionId) return;
    try {
      const amountNum = parseFloat(editTransactionAmount);
      if (isNaN(amountNum) || amountNum <= 0) throw new Error("Montant invalide");

      await updateTransaction(editingTransactionId, amountNum, editTransactionDescription);
      setNotification("Transaction mise à jour");
      setEditingTransactionId(null);
      (document.getElementById('edit_transaction_modal') as HTMLDialogElement)?.close();
      fetchBudgetData(budgetId);
    } catch (error) {
      setNotification("Erreur mise à jour transaction");
      console.error(error);
    }
  }


  return (
    <Wrapper>

      {notification && (
        < Notification message={notification} onclose={closeNotification}></Notification>
      )}
      {budget && (
        <div className='flex md:flex-row flex-col'>
          <div className='md:w-1/3'>
            <BudgetItem budget={budget} enableHover={0} />
            <div className="flex gap-2 mt-4">
              <button
                onClick={() => setIsEditBudgetModalOpen(true)}
                className='btn btn-primary flex-1'
              >
                <Pencil className='w-4 h-4 mr-2' /> Modifier
              </button>
              <button
                onClick={() => handleDeleteBudget()}
                className='btn btn-error flex-1'
              >
                <Trash className='w-4 h-4 mr-2' /> Supprimer
              </button>
            </div>

            <div className='space-y-4 flex flex-col mt-8 p-4 border rounded-xl bg-base-100 shadow-sm'>
              <h3 className="font-bold text-lg">Nouvelle Transaction</h3>
              <input
                type="text"
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Description"
                required
                className="input input-bordered"
              />

              <input
                type="number"
                id="amount"
                placeholder="Montant"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                required
                className=" input input-bordered"
              />

              <div className="form-control">
                <label className="label cursor-pointer justify-start">
                  <input
                    type="checkbox"
                    className="checkbox checkbox-accent mr-2"
                    checked={isRecurring}
                    onChange={(e) => setIsRecurring(e.target.checked)}
                  />
                  <span className="label-text">Transaction récurrente ?</span>
                </label>
              </div>

              {isRecurring && (
                <select
                  className="select select-bordered w-full"
                  value={frequency}
                  onChange={(e) => setFrequency(e.target.value)}
                >
                  <option value="DAILY">Journalier</option>
                  <option value="WEEKLY">Hebdomadaire</option>
                  <option value="MONTHLY">Mensuel</option>
                </select>
              )}

              <button
                onClick={handleAddTransaction}
                className="btn btn-accent text-white"
              >
                Ajouter la dépense
              </button>

            </div>
          </div>



          {/* Recurring Transactions Section */}
          <RecurringTransactionList
            transactions={recurringTransactions}
            onDelete={async (id) => {
              // Update local state is handled by parent refresh usually, but here we might want to refresh budget data
              fetchBudgetData(budgetId);
              setNotification("Récurrence supprimée avec succès");
            }}
          />

          {budget?.transactions && budget.transactions.length > 0 ? (
            <div className="overflow-x-auto md:mt-0 mt-4 md:w-2/3 ml-4 bg-base-100 rounded-xl shadow-sm border border-base-200">
              <table className="table table-zebra">
                {/* head */}
                <thead className="bg-base-200">
                  <tr>
                    <th >Type</th>
                    <th >Montant</th>
                    <th >Description</th>
                    <th >Date</th>
                    <th >Heure</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {budget?.transactions?.map((transaction) => (
                    <tr key={transaction.id}>
                      <td className='text-lg md:text-2xl text-center'>{transaction.emoji || budget.emoji}</td>
                      <td>
                        <div className="badge badge-accent badge-outline font-bold">
                          - {transaction.amount} FCFA</div>
                      </td>
                      <td className="font-medium">{transaction.description}</td>
                      <td className="text-sm text-gray-500">
                        {transaction.createdAt.toLocaleDateString("fr-FR")}
                      </td>
                      <td className="text-sm text-gray-500">
                        {transaction.createdAt.toLocaleTimeString("fr-FR", {
                          hour: "2-digit",
                          minute: "2-digit"
                        })}
                      </td>
                      <td className="flex gap-2">
                        <button
                          onClick={() => openEditTransactionModal(transaction)}
                          className='btn btn-ghost btn-xs text-info'
                        >
                          <Pencil className='w-4' />
                        </button>
                        <button
                          onClick={() => handleDeleteTransaction(transaction.id)}
                          className='btn btn-ghost btn-xs text-error'
                        >
                          <Trash className='w-4' />
                        </button>
                      </td>
                    </tr>
                  ))}

                </tbody>
              </table>
            </div>
          ) : (
            <div className='md:w-2/3 mt-10 md:ml-4 flex items-center justify-center flex-col p-10 border-2 border-dashed rounded-xl'>
              <Send strokeWidth={1.5} className='w-12 h-12 text-accent mb-4' />
              <span className='text-xl font-bold text-gray-500'>Aucune transaction.</span>
              <p className="text-gray-400">Ajoutez votre première dépense ci-contre.</p>
            </div>
          )}
        </div>
      )}

      {/* Edit Budget Modal */}
      {isEditBudgetModalOpen && (
        <div className="modal modal-open">
          <div className="modal-box">
            <h3 className="font-bold text-lg mb-4">Modifier le Budget</h3>
            <div className="form-control w-full mb-4">
              <label className="label"><span className="label-text">Nom</span></label>
              <input type="text" className="input input-bordered w-full" value={editBudgetName} onChange={e => setEditBudgetName(e.target.value)} />
            </div>
            <div className="form-control w-full mb-4">
              <label className="label"><span className="label-text">Montant (FCFA)</span></label>
              <input type="number" className="input input-bordered w-full" value={editBudgetAmount} onChange={e => setEditBudgetAmount(e.target.value)} />
            </div>

            <div className="form-control w-full mb-4">
              <label className="label"><span className="label-text">Icône</span></label>
              <div className="flex items-center gap-4">
                <button className="btn btn-outline text-2xl" onClick={() => setShowEmojiPicker(!showEmojiPicker)}>{editBudgetEmoji || "Choose"}</button>
                {showEmojiPicker && (
                  <div className="absolute z-10 mt-12 bg-white shadow-xl rounded-xl">
                    <EmojiPicker onEmojiClick={(e) => { setEditBudgetEmoji(e.emoji); setShowEmojiPicker(false) }} />
                  </div>
                )}
              </div>
            </div>

            <div className="modal-action">
              <button className="btn" onClick={() => setIsEditBudgetModalOpen(false)}>Annuler</button>
              <button className="btn btn-primary" onClick={handleUpdateBudget}>Enregistrer</button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Transaction Modal */}
      <dialog id="edit_transaction_modal" className="modal">
        <div className="modal-box">
          <h3 className="font-bold text-lg mb-4">Modifier la Transaction</h3>
          <div className="form-control w-full mb-4">
            <label className="label"><span className="label-text">Description</span></label>
            <input type="text" className="input input-bordered w-full" value={editTransactionDescription} onChange={e => setEditTransactionDescription(e.target.value)} />
          </div>
          <div className="form-control w-full mb-4">
            <label className="label"><span className="label-text">Montant (FCFA)</span></label>
            <input type="number" className="input input-bordered w-full" value={editTransactionAmount} onChange={e => setEditTransactionAmount(e.target.value)} />
          </div>
          <div className="modal-action">
            <button className="btn" onClick={() => (document.getElementById('edit_transaction_modal') as HTMLDialogElement)?.close()}>Annuler</button>
            <button className="btn btn-primary" onClick={handleUpdateTransaction}>Sauvegarder</button>
          </div>
        </div>
      </dialog>

    </Wrapper>
  )
}

export default Page;

